import { API, graphqlOperation } from "aws-amplify";
import { create_list_edit_delete_work_shift_timings } from "@/graphql/mutations.js";
export default {
  props: {
    createShiftDialog: Boolean
  },
  data() {
    return {
      shiftName: "",
      startTime: "09:00",
      endTime: "18:00",
      startDialog: false,
      endDialog: false,
      weekDays: ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"],
      weekoffDays: [],
      loading: false
    };
  },
  methods: {
    close_dialog() {
      this.$emit("clicked", 0);
      this.resetForm();
    },
    async validate_data() {
      const {
        valid
      } = await this.$refs.form.validate();
      if (valid) {
        this.save_Shift();
      }
    },
    resetForm() {
      this.shiftName = "";
      this.startTime = "09:00";
      this.endTime = "18:00";
      this.weekoffDays = [];
    },
    async save_Shift() {
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(create_list_edit_delete_work_shift_timings, {
          input: {
            action_type: "CREATE",
            work_shift_timings_name: this.shiftName,
            work_shift_start_timings: this.startTime,
            work_shift_end_timings: this.endTime,
            week_off: this.weekoffDays.map(d => String(d))
          }
        }));
        this.loading = false;

        // FIX: correct response field name
        const raw = result.data.create_list_edit_delete_work_shift_timings;
        const response = JSON.parse(raw);
        if (response.Status === "SUCCESS") {
          this.$emit("successMsg", response.Message);
          this.$refs.form.resetValidation();
          this.$refs.form.reset();
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        const msg = error?.errors?.[0]?.message || error?.message || "Something went wrong while saving the shift.";
        this.$emit("errorMsg", msg);
      }
    }
  }
};
